"""J2 (ii): pre-classify every token from j2_scan.out, then group TIME/RHO candidates by sentence
for hand review. Pre-classes: MEM (a memory figure), CAND (a possible time or rho figure),
OTHER (parameter, count, identifier, tolerance, digest, line number, version, date, ratio).
The pre-class is a filter for review, not a verdict: every CAND sentence is reviewed by hand,
and OTHER is spot-checked (the review notes say which)."""
import json
import re
import sys
from collections import OrderedDict

SCR = sys.argv[1]
d = json.load(open(f"{SCR}/j2_scan.out"))

MEMKW = re.compile(r"(rows?\b|store|dense|entries|MR_B|MR_M|MR_C8|MR_MAC|MR_F4|W\(N5|W\(\d|memory|Macaulay|binom|nvar|relation term)", re.I)
TIMEKW = re.compile(r"(cost|C_I|stage ?1|stage1|stage 2|margin|bits?\b|move|gap|time|advantage|total|work|iterations|operations|A\(|A_MI1|A_ceiled|log2_cost|drop|lower|step|anchor|per-solve)", re.I)
OMEGAS = {"2.376", "2.807", "3.0", "2.0", "2.978", "3", "2.37"}
EXCL_DEC = {"0.5", "0.05", "0.01", "0.886", "1.069993", "1.684211", "0.25", "0.1742519", "1.6986", "0.175", "4.579"}


def preclass(t):
    tok = t["token"]
    s = t["sentence"]
    # find token position in sentence (first occurrence)
    pos = s.find(tok)
    left = s[max(0, pos - 70):pos] if pos >= 0 else ""
    right = s[pos + len(tok):pos + len(tok) + 25] if pos >= 0 else ""
    if re.fullmatch(r"\d+", tok):
        # unsigned integer: candidate only with a time cue right beside it
        if re.match(r"\s*bits?\b", right) or re.search(r"(about|total|cost|advantage|log2 cost|log2_cost)\s*$", left):
            return "CAND"
        return "OTHER"
    if "e" in tok.lower():
        return "OTHER"          # tolerances and residuals in scientific notation (reviewed below)
    if tok in OMEGAS or tok in EXCL_DEC:
        return "OTHER"
    if re.fullmatch(r"[-+]\d+", tok):
        return "CAND" if TIMEKW.search(left + right) else "OTHER"
    near_left = left[-45:]
    lm = [m.end() for m in MEMKW.finditer(near_left)]
    lt = [m.end() for m in TIMEKW.finditer(near_left)]
    if lm and (not lt or max(lm) >= max(lt)):
        return "MEM"
    return "CAND"


for t in d["tokens"]:
    t["pre"] = preclass(t)

groups = OrderedDict()
for t in d["tokens"]:
    if t["pre"] != "CAND":
        continue
    key = (t["file"], t["status"], t["sentence"])
    g = groups.setdefault(key, {"file": t["file"], "status": t["status"], "field": t.get("field"),
                                "lines": [], "cands": [], "item": t["item"], "sentence": t["sentence"],
                                "mem_tokens_in_sentence": []})
    g["lines"].append(t["line"])
    g["cands"].append(t["token"])
# memory tokens per sentence
for t in d["tokens"]:
    if t["pre"] == "MEM":
        key = (t["file"], t["status"], t["sentence"])
        if key in groups:
            groups[key]["mem_tokens_in_sentence"].append(t["token"])
out = list(groups.values())
summary = {}
for t in d["tokens"]:
    summary.setdefault(t["pre"], 0)
    summary[t["pre"]] += 1
print(json.dumps({"preclass_counts": summary, "n_cand_sentences": len(out), "groups": out}, indent=0))

